#!/bin/bash

# Проверяем, что параметр max_connections установлен и равен 200
grep -q 'max_connections=200' /etc/app/app.conf && {
    echo "Параметр max_connections уже установлен и равен 200."
    exit 0
}

# Проверяем, что параметр max_connections закомментирован и раскомментируем его
grep -q '^#max_connections=' /etc/app/app.conf && {
    sed -i 's/^#max_connections=/max_connections=/' /etc/app/app.conf
    echo "Параметр max_connections успешно раскомментирован и установлен."
    exit 0
}

# Проверяем, что параметр max_connections отсутствует и добавляем его
grep -q '^max_connections=' /etc/app/app.conf || {
    echo "Параметр max_connections отсутствует. Добавляем."
    echo "max_connections=200" >> /etc/app/app.conf
    exit 0
}

# Если ничего из вышеуказанного не сработало, выводим сообщение об ошибке
echo "Не удалось установить параметр max_connections равным 200."
exit 1

